using System;
class DataPipeline { static void Main() { int valid = 0, invalid = 0, total = 0; Console.WriteLine("Enter name,amount rows"); while (true) { var s = Console.ReadLine(); if (string.IsNullOrEmpty(s)) break; var p = s.Split(','); int n; if (p.Length == 2 && int.TryParse(p[1].Trim(), out n)) { valid++; total += n; Console.WriteLine("accepted " + p[0].Trim() + ": " + n); } else { invalid++; Console.WriteLine("rejected: " + s); } } Console.WriteLine($"summary valid={valid} invalid={invalid} total={total}"); } }
